use crate::error::LexError;

/// One piece of a log line, borrowed from the line itself.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Token<'a> {
    /// The text between `[` and `]`.
    Timestamp(&'a str),
    /// The name in front of `=`.
    Key(&'a str),
    /// A double-quoted value without its quotes, escapes left as written.
    Quoted(&'a str),
    /// An unquoted value; empty for `key=` followed by a space or the end of the line.
    Bare(&'a str),
    /// A run of characters that is neither a timestamp nor part of a pair.
    Word(&'a str),
}

/// Streams the tokens of one line. After the first error it yields nothing more.
#[derive(Debug, Clone)]
pub struct Tokens<'a> {
    src: &'a str,
    pos: usize,
    state: State,
}

/// What the tokenizer expects at `pos`.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum State {
    /// Separators, then a timestamp, key or word.
    Token,
    /// The value of the key just read, directly after its `=`.
    Value,
    /// Nothing: an error has been reported.
    Failed,
}

type LexResult<'a> = Result<Token<'a>, LexError>;

impl<'a> Tokens<'a> {
    pub fn new(src: &'a str) -> Self {
        Tokens { src, pos: 0, state: State::Token }
    }

    fn bytes(&self) -> &'a [u8] {
        self.src.as_bytes()
    }

    /// Reads a timestamp, key or word; `None` once only separators are left.
    fn token(&mut self) -> Option<LexResult<'a>> {
        let start = skip_separators(self.bytes(), self.pos);
        self.pos = start;
        let &first = self.bytes().get(start)?;
        Some(match first {
            b'[' => self.timestamp(start),
            b'"' => Err(LexError::UnexpectedQuote { pos: start }),
            b'=' => Err(LexError::EmptyKey { pos: start }),
            _ => self.key_or_word(start),
        })
    }

    fn timestamp(&mut self, open: usize) -> LexResult<'a> {
        let close = find_timestamp_end(self.bytes(), open)?;
        expect_separator(self.bytes(), close + 1)?;
        self.pos = close + 1;
        Ok(Token::Timestamp(&self.src[open + 1..close]))
    }

    fn key_or_word(&mut self, start: usize) -> LexResult<'a> {
        let end = scan_unquoted(self.bytes(), start, |b| is_separator(b) || b == b'=')?;
        let text = &self.src[start..end];
        if self.bytes().get(end) == Some(&b'=') {
            self.state = State::Value;
            self.pos = end + 1;
            Ok(Token::Key(text))
        } else {
            self.pos = end;
            Ok(Token::Word(text))
        }
    }

    fn value(&mut self) -> LexResult<'a> {
        self.state = State::Token;
        let start = self.pos;
        if self.bytes().get(start) == Some(&b'"') {
            self.quoted(start)
        } else {
            self.bare(start)
        }
    }

    fn quoted(&mut self, open: usize) -> LexResult<'a> {
        let close = find_closing_quote(self.bytes(), open)?;
        expect_separator(self.bytes(), close + 1)?;
        self.pos = close + 1;
        Ok(Token::Quoted(&self.src[open + 1..close]))
    }

    /// An empty value when `start` is a separator or the end of the line.
    fn bare(&mut self, start: usize) -> LexResult<'a> {
        let end = scan_unquoted(self.bytes(), start, is_separator)?;
        self.pos = end;
        Ok(Token::Bare(&self.src[start..end]))
    }
}

/// Tokenizes one log line without copying any of it.
pub fn tokenize(line: &str) -> Tokens<'_> {
    Tokens::new(line)
}

impl<'a> Iterator for Tokens<'a> {
    type Item = LexResult<'a>;

    fn next(&mut self) -> Option<Self::Item> {
        let result = match self.state {
            State::Token => self.token()?,
            State::Value => self.value(),
            State::Failed => return None,
        };
        if result.is_err() {
            self.state = State::Failed;
            self.pos = self.src.len();
        }
        Some(result)
    }
}

fn is_separator(b: u8) -> bool {
    b == b' ' || b == b'\t'
}

fn skip_separators(bytes: &[u8], from: usize) -> usize {
    bytes[from..]
        .iter()
        .position(|&b| !is_separator(b))
        .map_or(bytes.len(), |offset| from + offset)
}

/// The value or token after a timestamp or quoted value has to be separated from it.
fn expect_separator(bytes: &[u8], at: usize) -> Result<(), LexError> {
    match bytes.get(at) {
        Some(&b) if !is_separator(b) => Err(LexError::ExpectedSeparator { pos: at }),
        _ => Ok(()),
    }
}

/// Returns the index of the `]` that closes the `[` at `open`.
fn find_timestamp_end(bytes: &[u8], open: usize) -> Result<usize, LexError> {
    let inner = open + 1;
    match bytes[inner..].iter().position(|&b| b == b']' || b == b'[') {
        None => Err(LexError::UnterminatedTimestamp { pos: open }),
        Some(offset) if bytes[inner + offset] == b'[' => {
            Err(LexError::NestedBracket { pos: inner + offset })
        }
        Some(offset) => Ok(inner + offset),
    }
}

/// Returns the index of the `"` that closes the `"` at `open`, checking escapes on the way.
fn find_closing_quote(bytes: &[u8], open: usize) -> Result<usize, LexError> {
    let unterminated = LexError::UnterminatedQuote { pos: open };
    let mut i = open + 1;
    loop {
        match bytes.get(i) {
            None => return Err(unterminated),
            Some(b'"') => return Ok(i),
            Some(b'\\') => match bytes.get(i + 1) {
                None => return Err(unterminated),
