mod error;
#[path = "old_token.rs"] mod old;
#[path = "new_token.rs"] mod new;
use std::hint::black_box;
use std::time::Instant;

struct Rng(u64);
impl Rng { fn next(&mut self) -> u64 { self.0 ^= self.0 << 13; self.0 ^= self.0 >> 7; self.0 ^= self.0 << 17; self.0 } }

fn fuzz_line(r: &mut Rng) -> String {
    const ALPHA: &[&str] = &["a", "b", "=", "\"", "\\", "[", "]", " ", "\t", "n", "t", "ä", "x\\\"y", "k=", "=\"", "\" ", "] "];
    let len = (r.next() % 14) as usize;
    (0..len).map(|_| ALPHA[(r.next() % ALPHA.len() as u64) as usize]).collect()
}

fn realistic_line(r: &mut Rng, i: u64) -> String {
    match r.next() % 10 {
        0 => format!("[2024-05-01T12:{:02}:{:02}Z] level=warn msg=\"open \\\"cfg\\\"\" bad\"x", i % 60, i % 60),
        1..=3 => format!("[2024-05-01T12:00:{:02}Z] started worker-{} ok retries= done", i % 60, i % 17),
        _ => format!("[2024-05-01T12:00:{:02}.{:06}Z] level=info service=api-gateway req_id={} msg=\"disk {}% full on /var/lib\\tdata\" user=ann latency_ms={} path=/v1/items/{}", i % 60, i, i * 7919, i % 100, i % 900, i),
    }
}

fn count_old(lines: &[String]) -> u64 { let mut c = 0; for l in lines { for t in old::tokenize(l) { c += match t { Ok(old::Token::Key(s)) => s.len() as u64, Ok(_) => 1, Err(_) => 3 }; } } c }
fn count_new(lines: &[String]) -> u64 { let mut c = 0; for l in lines { for t in new::tokenize(l) { c += match t { Ok(new::Token::Key(s)) => s.len() as u64, Ok(_) => 1, Err(_) => 3 }; } } c }

fn main() {
    let mut r = Rng(0x9e3779b97f4a7c15);
    for _ in 0..2_000_000 {
        let l = fuzz_line(&mut r);
        let a: Vec<String> = old::tokenize(&l).map(|t| format!("{t:?}")).collect();
        let b: Vec<String> = new::tokenize(&l).map(|t| format!("{t:?}")).collect();
        assert_eq!(a, b, "line {l:?}");
    }
    println!("differential: 2000000 random lines identical");

    let lines: Vec<String> = (0..1_000_000).map(|i| realistic_line(&mut r, i)).collect();
    let bytes: usize = lines.iter().map(|l| l.len()).sum();
    assert_eq!(count_old(&lines), count_new(&lines));
    for round in 0..3 {
        for (name, f) in [("old", count_old as fn(&[String]) -> u64), ("new", count_new)] {
            let mut best = f64::MAX;
            for _ in 0..5 { let t = Instant::now(); black_box(f(black_box(&lines))); best = best.min(t.elapsed().as_secs_f64()); }
            println!("round {round} {name}: best {:.1} ms, {:.0} MB/s", best * 1e3, bytes as f64 / best / 1e6);
        }
    }
}
EOF
